input.content:
:root {
  --gold: #ffd15c;
  --gold-bright: #ffe89a;
  --gold-deep: #d9901f;
  --ink: #0b1024;
  --ink-2: #131c3c;
  --cream: #fff8e7;
  --red: #ff5d62;
  --blue: #4d7dff;
  --teal: #52e0c4;
  --panel: linear-gradient(165deg, #1c2850 0%, #111936 55%, #0a0f24 100%);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--ink);
}

body {
  font-family: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  color: var(--cream);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #0b1024;
  isolation: isolate;
}

canvas#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.hidden { display: none !important; }

/* ---------- HUD ---------- */

.hud {
  position: absolute;
  inset: 0 0 auto 0;
  z-index: 10;
  padding: calc(10px + var(--safe-top)) calc(14px + var(--safe-right)) 0 calc(14px + var(--safe-left));
  pointer-events: none;
}

.hud-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.hud-left { display: flex; flex-direction: column; gap: 7px; min-width: 0; }
.hud-right { display: flex; align-items: center; gap: 7px; margin-left: auto; }

.hearts { display: flex; gap: 2px; height: 22px; align-items: center; }
.heart {
  font-size: 21px;
  line-height: 1;
  color: #ff5d62;
  text-shadow: 0 2px 0 #7a1c2e, 0 0 10px rgba(255, 93, 98, .45);
  transition: transform .2s ease, color .2s ease, opacity .2s ease;
}
.heart.empty { color: rgba(255, 248, 231, .16); text-shadow: none; }
.heart.pop { animation: heartPop .45s ease; }
@keyframes heartPop { 0% { transform: scale(1.5); } 100% { transform: scale(1); } }

.jump-shell { width: 168px; max-width: 34vw; }
.jump-top {
  display: flex; justify-content: space-between; align-items: baseline;
  margin-bottom: 3px;
  font-size: 9px; letter-spacing: .16em; font-weight: 700;
  color: rgba(255, 248, 231, .7);
  text-shadow: 0 1px 2px rgba(0,0,0,.5);
}
.jump-top b { font-size: 11px; letter-spacing: .02em; color: var(--gold); }
.jump-bar {
  height: 9px; border-radius: 999px; overflow: hidden;
  background: rgba(6, 10, 24, .55);
  border: 1px solid rgba(255,255,255,.16);
  box-shadow: inset 0 2px 5px rgba(0,0,0,.55);
}
.jump-fill {
  height: 100%; width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, #ffb642, #ffe58a 60%, #fff5c2);
  box-shadow: 0 0 12px rgba(255, 207, 77, .55);
  transition: width .28s cubic-bezier(.2,.8,.3,1);
}
.jump-shell.hot .jump-fill { background: linear-gradient(90deg, #ff8b3d, #ffd15c 50%, #fffbd0); box-shadow: 0 0 18px rgba(255, 167, 66, .85); animation: meterGlow 1.2s ease-in-out infinite alternate; }
.jump-shell.max .jump-fill { background: linear-gradient(90deg, #ff5d62, #ffd15c 45%, #52e0c4 100%); }
@keyframes meterGlow { from { filter: brightness(1); } to { filter: brightness(1.25); } }

.hud-center { flex: 0 1 auto; display: flex; justify-content: center; padding-top: 2px; }
.level-chip {
  display: flex; flex-direction: column; align-items: center;
  padding: 4px 14px 5px;
  border-radius: 12px;
  background: rgba(9, 14, 32, .4);
  border: 1px solid rgba(255,255,255,.12);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.level-chip span { font-size: 8.5px; letter-spacing: .2em; color: var(--gold); font-weight: 800; }
.level-chip b { font-size: 11px; font-weight: 700; color: rgba(255,248,231,.9); white-space: nowrap; }

.coin-chip {
  display: flex; align-items: center; gap: 6px;
  height: 34px; padding: 0 11px 0 9px;
  border-radius: 999px;
  background: rgba(9, 14, 32, .5);
  border: 1px solid rgba(255,255,255,.14);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  font-size: 14px;
}
.coin-dot {
  width: 15px; height: 15px; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff6c8, #ffd15c 42%, #e39b1e 78%, #a96310);
  border: 1px solid #7a4610;
  box-shadow: 0 0 9px rgba(255,209,92,.55);
  position: relative;
}
.coin-dot::after { content: ""; position: absolute; inset: 4px; border-radius: 50%; border: 1px solid rgba(122,70,16,.55); }
.coin-chip b { color: var(--gold-bright); font-size: 15px; font-variant-numeric: tabular-nums; }
.coin-total { font-size: 10px; color: rgba(255,248,231,.5); margin-left: -2px; }

.time-chip {
  font-size: 12px; font-variant-numeric: tabular-nums;
  color: rgba(255,248,231,.78);
  padding: 0 4px;
  text-shadow: 0 1px 3px rgba(0,0,0,.6);
}

.round-btn {
  appearance: none; border: 1px solid rgba(255,255,255,.18);
  width: 36px; height: 36px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(9, 14, 32, .5);
  color: rgba(255,248,231,.9);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  cursor: pointer; pointer-events: auto;
  transition: transform .12s ease, background .12s ease;
  touch-action: manipulation;
}
.round-btn:active { transform: scale(.92); background: rgba(255, 207, 77, .2); }
.round-btn svg { width: 18px; height: 18px; overflow: visible; }
.round-btn .mute-slash { display: none; }
.round-btn.muted .mute-slash { display: block; }
.round-btn.muted { color: rgba(255, 248, 231, .45); }

/* ---------- Touch controls ---------- */

.touch {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  z-index: 12;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding: 0 calc(22px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(22px + var(--safe-left));
  pointer-events: none;
}
body:not(.touch-mode) .touch { display: none !important; }

.touch-move { display: flex; gap: 14px; }
.tbtn {
  pointer-events: auto;
  touch-action: none;
  appearance: none;
  border: 2px solid rgba(255,255,255,.3);
  background: rgba(10, 17, 40, .3);
  color: rgba(255,248,231,.92);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  box-shadow: 0 6px 18px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.22);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  width: clamp(62px, 12.5vmin, 84px);
  height: clamp(62px, 12.5vmin, 84px);
  border-radius: 50%;
  transition: transform .08s ease, background .1s ease, border-color .1s ease;
  user-select: none;
}
.tbtn:active, .tbtn.active {
  transform: scale(.93);
  background: rgba(255, 207, 77, .32);
  border-color: rgba(255, 232, 154, .85);
}
.tbtn.jump {
  width: clamp(76px, 16vmin, 100px);
  height: clamp(76px, 16vmin, 100px);
  border-color: rgba(255, 207, 77, .62);
  background: radial-gradient(circle at 40% 30%, rgba(255,232,154,.3), rgba(217,144,31,.14) 55%, rgba(10,17,40,.36));
}
.tbtn.jump:active, .tbtn.jump.active {
  background: radial-gradient(circle at 40% 30%, rgba(255,240,180,.7), rgba(255,166,54,.5));
}
.chev {
  width: 16px; height: 16px;
  border-left: 5px solid currentColor;
  border-bottom: 5px solid currentColor;
  border-radius: 2px;
  transform: rotate(45deg);
  margin-left: 5px;
  filter: drop-shadow(0 2px 2px rgba(0,0,0,.3));
}
.chev.left { transform: rotate(135deg); margin-left: 0; margin-right: 5px; }
.jump-arrow {
  width: 0; height: 0;
  border-left: 9px solid transparent;
  border-right: 9px solid transparent;
  border-bottom: 13px solid currentColor;
  margin-bottom: 3px;
  filter: drop-shadow(0 2px 2px rgba(0,0,0,.25));
}
.jump-text { font-size: 9px; letter-spacing: .16em; font-weight: 800; opacity: .85; }

/* ---------- Banner + toast ---------- */

.banner {
  position: absolute; top: 17%; left: 50%;
  transform: translate(-50%, 10px);
  z-index: 14;
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  text-align: center; pointer-events: none;
  opacity: 0;
  padding: 10px 26px;
  border-radius: 18px;
  background: radial-gradient(ellipse at center, rgba(9,14,32,.6), rgba(9,14,32,0) 72%);
  text-shadow: 0 3px 12px rgba(0,0,0,.55);
}
.banner.show { animation: bannerIn 2.5s ease forwards; }
@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, 14px) scale(.96); }
  12% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  78% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -10px) scale(1); }
}
.banner-kicker { font-size: 10px; letter-spacing: .3em; color: var(--gold); font-weight: 800; }
.banner-title { font-size: clamp(22px, 3.6vw, 38px); font-family: "Arial Black", "Trebuchet MS", sans-serif; letter-spacing: -.01em; color: var(--cream); }
.banner-sub { font-size: 11px; color: rgba(255,248,231,.7); letter-spacing: .02em; }

.toast {
  position: absolute; left: 50%; bottom: 21%;
  transform: translate(-50%, 8px);
  z-index: 14;
  padding: 8px 18px;
  border-radius: 999px;
  background: rgba(9, 14, 32, .78);
  border: 1px solid rgba(255, 207, 77, .35);
  color: var(--gold-bright);
  font-size: 11px; font-weight: 800; letter-spacing: .12em;
  opacity: 0; pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Screens ---------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: calc(22px + var(--safe-top)) calc(22px + var(--safe-right)) calc(22px + var(--safe-bottom)) calc(22px + var(--safe-left));
}

.title-screen {
  z-index: 32;
  justify-content: center;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 38%, rgba(8, 13, 32, .18) 0%, rgba(8, 13, 32, .62) 62%, rgba(8, 13, 32, .88) 100%),
    linear-gradient(180deg, rgba(8,13,32,.45), rgba(8,13,32,.15) 40%, rgba(8,13,32,.7));
}
.title-shade {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 42%, transparent 20%, rgba(5,8,20,.5) 100%);
  pointer-events: none;
}
.title-content {
  position: relative;
  z-index: 2;
  display: flex; flex-direction: column; align-items: center;
  text-align: center;
  width: min(92vw, 780px);
  padding-top: 2vh;
}
.eyebrow {
  display: flex; align-items: center; gap: 9px;
  font-size: clamp(8.5px, 1.1vw, 11px);
  letter-spacing: .34em;
  font-weight: 800;
  color: rgba(255, 232, 154, .88);
  padding: 7px 15px;
  border: 1px solid rgba(255, 207, 77, .26);
  border-radius: 999px;
  background: rgba(9, 14, 32, .4);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  margin-bottom: clamp(12px, 2.2vh, 22px);
}
.eyebrow-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 10px var(--gold); }

.logo { margin: 0; font-family: "Arial Black", "Trebuchet MS", sans-serif; line-height: .92; }
.logo-super {
  display: block;
  font-size: clamp(11px, 1.55vw, 16px);
  letter-spacing: .58em;
  color: var(--gold);
  margin: 0 0 10px .58em;
  text-shadow: 0 2px 0 #8a5410, 0 0 18px rgba(255,209,92,.3);
}
.logo-main {
  display: block;
  font-size: clamp(3.1rem, 9.2vw, 6.6rem);
  letter-spacing: -.035em;
  color: #fff8e7;
  text-shadow:
    0 3px 0 #16224a,
    0 7px 0 #0a1027,
    0 10px 22px rgba(0,0,0,.6);
  -webkit-text-stroke: 1px rgba(255,255,255,.12);
}
.logo-accent {
  background: linear-gradient(178deg, #fff2b0 8%, #ffd15c 38%, #f0a12c 72%, #ffd868 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 4px 0 #7d470c) drop-shadow(0 8px 12px rgba(0,0,0,.35));
}
.tagline {
  margin: clamp(12px, 2.4vh, 20px) 0 clamp(18px, 3.2vh, 30px);
  font-size: clamp(13px, 1.8vw, 18px);
  letter-spacing: .02em;
  color: rgba(255, 248, 231, .82);
}
.tagline em {
  font-style: normal; color: var(--gold-bright);
  border-bottom: 2px solid rgba(255, 209, 92, .45);
  padding-bottom: 1px;
}

.btn {
  appearance: none;
  border: 0;
  border-radius: 16px;
  font-family: inherit;
  font-weight: 800;
  letter-spacing: .08em;
  font-size: 13px;
  padding: 14px 22px;
  cursor: pointer;
  color: var(--cream);
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.14);
  transition: transform .12s ease, filter .12s ease, box-shadow .12s ease, background .12s ease;
  touch-action: manipulation;
}
.btn:active { transform: translateY(2px) scale(.99); }
.btn-primary {
  color: #3a2202;
  background: linear-gradient(180deg, #fff0a8 0%, #ffd15c 38%, #f2a62b 100%);
  border: 1px solid rgba(255, 248, 214, .7);
  box-shadow:
    0 6px 0 #a85f10,
    0 12px 26px rgba(255, 166, 43, .25),
    inset 0 2px 0 rgba(255,255,255,.6);
  text-shadow: 0 1px 0 rgba(255,255,255,.4);
}
.btn-primary:hover { filter: brightness(1.06); }
.btn-primary:active { box-shadow: 0 3px 0 #a85f10, 0 6px 14px rgba(255,166,43,.2), inset 0 2px 0 rgba(255,255,255,.5); }
.btn-ghost { background: rgba(255,255,255,.06); color: rgba(255,248,231,.82); }
.btn-ghost:hover { background: rgba(255,255,255,.11); }
.btn.wide { width: 100%; }

.play-btn {
  display: inline-flex; align-items: center; gap: 14px;
  font-size: clamp(16px, 2.1vw, 21px);
  letter-spacing: .16em;
  padding: clamp(15px, 2.2vh, 21px) clamp(42px, 6vw, 66px);
  border-radius: 20px;
  animation: playPulse 2.8s ease-in-out infinite;
}
@keyframes playPulse {
  0%, 100% { box-shadow: 0 6px 0 #a85f10, 0 12px 26px rgba(255,166,43,.25), inset 0 2px 0 rgba(255,255,255,.6), 0 0 0 0 rgba(255,209,92,.28); }
  50% { box-shadow: 0 6px 0 #a85f10, 0 12px 34px rgba(255,166,43,.4), inset 0 2px 0 rgba(255,255,255,.6), 0 0 0 16px rgba(255,209,92,0); }
}
.play-icon {
  width: 0; height: 0;
  border-top: 9px solid transparent;
  border-bottom: 9px solid transparent;
  border-left: 15px solid #3a2202;
  filter: drop-shadow(0 1px 0 rgba(255,255,255,.35));
}

.how {
  display: flex; gap: clamp(8px, 1.4vw, 14px);
  margin-top: clamp(20px, 4vh, 36px);
  flex-wrap: wrap; justify-content: center;
}
.how-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 14px 8px 9px;
  border-radius: 14px;
  background: rgba(9, 14, 32, .42);
  border: 1px solid rgba(255,255,255,.1);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  text-align: left;
}
.how-icon {
  width: 34px; height: 34px; border-radius: 10px;
  display: grid; place-items: center;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.1);
  color: var(--gold-bright);
  font-size: 13px; font-weight: 800;
  flex: 0 0 auto;
}
.how-icon.space { font-size: 18px; }
.how-icon.coin-ico {
  background: radial-gradient(circle at 35% 30%, #fff6c8, #ffd15c 42%, #e39b1e 82%);
  border: 1px solid #9d5e0d;
  box-shadow: inset 0 0 0 4px rgba(158, 94, 13, .18);
}
.how-item b { display: block; font-size: 9px; letter-spacing: .16em; color: var(--gold); margin-bottom: 1px; }
.how-item small { display: block; font-size: 10px; color: rgba(255,248,231,.62); }

.title-meta {
  margin-top: clamp(16px, 3vh, 26px);
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: center;
  font-size: 10.5px; color: rgba(255,248,231,.5);
  letter-spacing: .04em;
}
.dot-sep { opacity: .45; }

.title-footer {
  position: absolute; bottom: calc(16px + var(--safe-bottom)); left: 0; right: 0;
  display: flex; justify-content: center; gap: 8px; flex-wrap: wrap;
  font-size: 9px; letter-spacing: .22em; font-weight: 700;
  color: rgba(255,255,255,.3); z-index: 2;
}

.drift-coin {
  position: absolute;
  width: clamp(18px, 2.6vw, 30px); aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff6c8, #ffd15c 42%, #e39b1e 78%, #a96310);
  border: 2px solid rgba(122, 70, 16, .8);
  box-shadow: inset 0 0 0 4px rgba(122,70,16,.15), 0 0 18px rgba(255,209,92,.35);
  opacity: .8;
  animation: drift 9s ease-in-out infinite;
  z-index: 1;
}
.drift-coin::after {
  content: "★"; position: absolute; inset: 0;
  display: grid; place-items: center;
  font-size: 10px; color: rgba(122,70,16,.75);
}
.drift-coin.c1 { left: 11%; top: 31%; animation-delay: -1s; }
.drift-coin.c2 { right: 9%; top: 23%; width: clamp(13px, 2vw, 22px); animation-delay: -4s; }
.drift-coin.c3 { left: 17%; bottom: 24%; width: clamp(12px, 1.7vw, 20px); animation-delay: -6s; }
.drift-coin.c4 { right: 15%; bottom: 31%; animation-delay: -2.5s; }
@keyframes drift {
  0%, 100% { transform: translateY(0) rotateY(0deg) rotateZ(-8deg); }
  50% { transform: translateY(-18px) rotateY(180deg) rotateZ(8deg); }
}

/* ---------- Panels ---------- */

.overlay {
  z-index: 40;
  background: radial-gradient(ellipse at 50% 45%, rgba(8, 13, 32, .55), rgba(4, 7, 18, .84));
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.panel {
  position: relative;
  width: min(94vw, 460px);
  max-height: calc(100dvh - 32px);
  overflow: auto;
  padding: clamp(20px, 3.5vh, 32px) clamp(20px, 4vw, 32px);
  border-radius: 26px;
  background: var(--panel);
  border: 1px solid rgba(255, 207, 77, .22);
  box-shadow:
    0 30px 80px rgba(0, 0, 0, .58),
    inset 0 1px 0 rgba(255,255,255,.1),
    inset 0 0 60px rgba(255, 209, 92, .03);
  text-align: center;
  animation: panelPop .34s cubic-bezier(.2, 1.2, .35, 1);
}
@keyframes panelPop {
  from { opacity: 0; transform: translateY(18px) scale(.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.panel-kicker {
  font-size: 9px; letter-spacing: .32em; font-weight: 800;
  color: var(--gold); margin-bottom: 7px;
}
.panel-title {
  font-family: "Arial Black", "Trebuchet MS", sans-serif;
  font-size: clamp(24px, 4vw, 32px);
  letter-spacing: -.02em;
  margin: 0 0 16px;
  color: var(--cream);
  text-shadow: 0 3px 0 rgba(0,0,0,.35);
}
.panel-hint { font-size: 11.5px; line-height: 1.5; color: rgba(255,248,231,.58); margin: 12px 0 18px; }

.mini-stats, .result-grid {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 8px; margin: 0 0 20px;
}
.mini-stats { grid-template-columns: repeat(3, 1fr); }
.mini-stats > div, .result-grid > div {
  padding: 10px 6px;
  border-radius: 13px;
  background: rgba(255,255,255,.05);
  border: 1px solid rgba(255,255,255,.08);
}
.mini-stats span, .result-grid span {
  display: block; font-size: 8px; letter-spacing: .14em; font-weight: 700;
  color: rgba(255,248,231,.45); margin-bottom: 4px;
}
.mini-stats b, .result-grid b {
  font-size: 15px; color: var(--cream); font-variant-numeric: tabular-nums;
}
.result-grid b { font-size: 16px; color: var(--gold-bright); }
.result-grid.small { grid-template-columns: repeat(2, 1fr); }
.btn-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 10px; }
.btn-row .btn { font-size: 10.5px; padding: 12px 8px; letter-spacing: .06em; }

.medal, .trophy {
  width: 64px; height: 64px; border-radius: 50%;
  margin: 0 auto 14px;
  display: grid; place-items: center;
  background: radial-gradient(circle at 36% 28%, #fff8ce, #ffd15c 45%, #dc921c 82%);
  border: 3px solid rgba(255, 248, 206, .8);
  box-shadow: 0 0 0 6px rgba(255, 209, 92, .1), 0 10px 30px rgba(255, 166, 43, .3);
