/* Tiny WebAudio synth: no samples, no network. */

const SONGS = [
  {
    step: 0.155,
    lead: [72, null, 76, null, 79, null, 76, null, 74, null, 77, null, 81, null, 79, null,
           72, null, 76, null, 79, null, 84, null, 83, null, 79, null, 76, null, 74, null],
    bass: [48, 53, 48, 55],
  },
  {
    step: 0.175,
    lead: [77, null, 81, null, 84, null, 81, null, 79, null, 76, null, 72, null, 74, null,
           77, null, 81, null, 86, null, 84, null, 81, null, 79, null, 76, null, 74, null],
    bass: [53, 48, 55, 48],
  },
  {
    step: 0.185,
    lead: [69, null, 72, null, 76, null, 72, null, 71, null, 68, null, 64, null, 68, null,
           69, null, 72, null, 76, null, 81, null, 79, null, 76, null, 72, null, 71, null],
    bass: [45, 41, 45, 43],
  },
];

const midiToFreq = (m) => 440 * Math.pow(2, (m - 69) / 12);

export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfx = null;
    this.music = null;
    this.muted = false;
    try { this.muted = localStorage.getItem('coinjump.muted') === '1'; } catch {}
    this.song = null;
    this.musicTimer = null;
    this.musicStep = 0;
    this.nextNote = 0;
    this.wantedSong = -1;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.9;
    this.master.connect(this.ctx.destination);

    this.sfx = this.ctx.createGain();
    this.sfx.gain.value = 0.5;
    this.sfx.connect(this.master);

    this.music = this.ctx.createGain();
    this.music.gain.value = 0.16;
    this.music.connect(this.master);
  }

  setMuted(muted) {
    this.muted = muted;
    try { localStorage.setItem('coinjump.muted', muted ? '1' : '0'); } catch {}
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.9, this.ctx.currentTime, 0.03);
    }
    if (muted) this.stopMusic();
  }

  tone(freq, dur, { type = 'square', vol = 0.1, slide = 1, delay = 0, attack = 0.006, music = false } = {}) {
    if (!this.ctx || !this.sfx) return;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (slide !== 1) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t0 + dur);
    }
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(vol, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain);
    gain.connect(music ? this.music : this.sfx);
    osc.start(t0);
    osc.stop(t0 + dur + 0.03);
  }

  jump(mult = 1) {
    this.init();
    const base = 290 + Math.min(mult, 2.4) * 120;
    this.tone(base, 0.16, { type: 'square', vol: 0.075, slide: 2.1 });
    this.tone(base * 0.5, 0.1, { type: 'triangle', vol: 0.05, slide: 1.6, delay: 0.01 });
  }

  coin(streak = 0) {
    this.init();
    const pitch = 1 + Math.min(streak, 24) * 0.014;
    this.tone(1046 * pitch, 0.07, { type: 'triangle', vol: 0.1, slide: 1.02 });
    this.tone(1568 * pitch, 0.12, { type: 'triangle', vol: 0.085, delay: 0.065, slide: 1.01 });
  }

  power() {
    this.init();
    [523, 659, 784, 1046, 1318].forEach((f, i) => {
      this.tone(f, 0.1, { type: 'square', vol: 0.055, delay: i * 0.045, slide: 1.02 });
    });
  }

  stomp() {
    this.init();
    this.tone(180, 0.12, { type: 'square', vol: 0.09, slide: 0.32 });
    this.tone(90, 0.1, { type: 'triangle', vol: 0.08, slide: 0.5, delay: 0.01 });
  }

  hurt() {
    this.init();
    this.tone(260, 0.3, { type: 'sawtooth', vol: 0.09, slide: 0.3 });
    this.tone(130, 0.32, { type: 'square', vol: 0.06, slide: 0.4, delay: 0.03 });
  }

  spring() {
    this.init();
    this.tone(170, 0.28, { type: 'triangle', vol: 0.1, slide: 6.2 });
    this.tone(340, 0.14, { type: 'square', vol: 0.04, slide: 3, delay: 0.02 });
  }

  checkpoint() {
    this.init();
    [523, 659, 784, 1046].forEach((f, i) => {
      this.tone(f, 0.16, { type: 'triangle', vol: 0.075, delay: i * 0.07, slide: 1.01 });
    });
  }

  block() {
    this.init();
    this.tone(150, 0.08, { type: 'square', vol: 0.08, slide: 0.7 });
  }

  fall() {
    this.init();
    this.tone(700, 0.42, { type: 'sine', vol: 0.07, slide: 0.16 });
  }

  click() {
    this.init();
    this.tone(760, 0.05, { type: 'triangle', vol: 0.05, slide: 1.1 });
  }

  clear() {
    this.init();
    [523, 659, 784, 1046, 1318, 1568].forEach((f, i) => {
      this.tone(f, i === 5 ? 0.5 : 0.18, { type: 'triangle', vol: 0.09, delay: i * 0.11, slide: 1.005 });
    });
  }

  win() {
    this.init();
    const seq = [523, 659, 784, 1046, 784, 1046, 1318, 1568];
    seq.forEach((f, i) => {
      this.tone(f, i === seq.length - 1 ? 0.8 : 0.22, {
        type: 'triangle', vol: 0.09, delay: i * 0.13, slide: 1.005,
      });
    });
    this.tone(261, 0.8, { type: 'triangle', vol: 0.05, delay: 0, slide: 1.01 });
  }

  gameover() {
    this.init();
    [392, 349, 294, 196].forEach((f, i) => {
      this.tone(f, 0.32, { type: 'triangle', vol: 0.085, delay: i * 0.18, slide: 0.98 });
    });
  }

  startMusic(theme = 0) {
    this.wantedSong = theme;
    if (this.muted) return;
    this.init();
    if (!this.ctx) return;
    this.stopMusic();
    this.song = SONGS[theme % SONGS.length];
    this.musicStep = 0;
    this.nextNote = this.ctx.currentTime + 0.1;
    if (this.music) this.music.gain.setTargetAtTime(0.16, this.ctx.currentTime, 0.08);
    this.scheduleMusic();
    this.musicTimer = setInterval(() => this.scheduleMusic(), 60);
  }

  scheduleMusic() {
    if (!this.ctx || !this.song) return;
    const ahead = this.ctx.currentTime + 0.32;
    let guard = 0;
    while (this.nextNote < ahead && guard++ < 12) {
      const i = this.musicStep;
      const lead = this.song.lead[i % this.song.lead.length];
      if (lead != null) {
        this.musicTone(midiToFreq(lead), this.song.step * 0.82, 'square', 0.035, this.nextNote);
      }
      if (i % 8 === 0) {
        const bass = this.song.bass[(Math.floor(i / 8)) % this.song.bass.length];
        this.musicTone(midiToFreq(bass), this.song.step * 6.4, 'triangle', 0.055, this.nextNote);
      }
      if (i % 4 === 2) {
        this.musicTone(midiToFreq(lead != null ? lead + 12 : 72), this.song.step * 0.3, 'sine', 0.012, this.nextNote);
      }
      this.nextNote += this.song.step;
      this.musicStep++;
    }
  }

  musicTone(freq, dur, type, vol, startTime) {
    if (!this.ctx || !this.music) return;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, startTime);
    gain.gain.setValueAtTime(0.0001, startTime);
    gain.gain.linearRampToValueAtTime(vol, startTime + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, startTime + dur);
    osc.connect(gain);
    gain.connect(this.music);
    osc.start(startTime);
    osc.stop(startTime + dur + 0.05);
  }

  stopMusic() {
    if (this.musicTimer) clearInterval(this.musicTimer);
    this.musicTimer = null;
    this.song = null;
  }

  resumeWantedMusic() {
    if (this.wantedSong >= 0 && !this.muted) this.startMusic(this.wantedSong);
  }
}

const $ = (id) => document.getElementById(id);

export function fmtTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  const m = Math.floor(s / 60);
  return `${m}:${String(s % 60).padStart(2, '0')}`;
}

export class UI {
  constructor() {
    this.el = {
      hud: $('hud'),
      touch: $('touch'),
      hearts: $('hearts'),
      jumpShell: document.querySelector('.jump-shell'),
      jumpFill: $('jumpFill'),
      jumpMult: $('jumpMult'),
      coinHud: $('coinHud'),
      coinTotal: $('coinTotal'),
      timeHud: $('timeHud'),
      worldLabel: $('worldLabel'),
      levelName: $('levelName'),
      banner: $('banner'),
      bannerKicker: $('bannerKicker'),
      bannerTitle: $('bannerTitle'),
      bannerSub: $('bannerSub'),
      toast: $('toast'),
      soundBtn: $('soundBtn'),
      pauseCoins: $('pauseCoins'),
      pauseJump: $('pauseJump'),
      pauseHearts: $('pauseHearts'),
      bestLine: $('bestLine'),
      clearTitle: $('clearTitle'),
      clearCoins: $('clearCoins'),
      clearTime: $('clearTime'),
      clearJump: $('clearJump'),
      clearFlavor: $('clearFlavor'),
      nextBtn: $('nextBtn'),
      gameoverLine: $('gameoverLine'),
      overCoins: $('overCoins'),
      overLevel: $('overLevel'),
      winCoins: $('winCoins'),
      winTime: $('winTime'),
      winBest: $('winBest'),
      winFlavor: $('winFlavor'),
      winBestLine: $('winBestLine'),
    };
    this.screens = ['titleScreen', 'pauseScreen', 'clearScreen', 'gameoverScreen', 'winScreen'];
    this.prev = { coins: -1, total: -1, time: -1, mult: -1, world: '', name: '', hot: null };
    this.bannerTimer = null;
    this.toastTimer = null;
    this.heartCount = -1;
    this.buildHearts(3);
  }

  buildHearts(max) {
    this.el.hearts.innerHTML = '';
    for (let i = 0; i < max; i++) {
      const h = document.createElement('span');
      h.className = 'heart';
      h.textContent = '♥';
      this.el.hearts.appendChild(h);
    }
  }

  setHearts(n) {
    const hearts = [...this.el.hearts.children];
    hearts.forEach((h, i) => {
      h.classList.toggle('empty', i >= n);
      if (n > this.heartCount && i < n) {
        h.classList.remove('pop');
        void h.offsetWidth;
        h.classList.add('pop');
        setTimeout(() => h.classList.remove('pop'), 500);
      }
    });
    this.heartCount = n;
  }

  showScreen(id) {
    for (const s of this.screens) {
      const el = $(s);
      if (el) el.classList.toggle('hidden', s !== id);
    }
  }

  showHUD(visible) {
    this.el.hud.classList.toggle('hidden', !visible);
    this.el.hud.setAttribute('aria-hidden', String(!visible));
  }

  setPlaying(active) {
    this.showHUD(active);
    this.el.touch.classList.toggle('hidden', !active);
    this.el.touch.setAttribute('aria-hidden', String(!active));
  }

  updateHUD({ coins, total, jumpMult, jumpPct, time, world, levelName, hot }) {
    const e = this.el;
    if (coins !== this.prev.coins) {
      e.coinHud.textContent = coins;
      this.prev.coins = coins;
    }
    if (total !== this.prev.total) {
      e.coinTotal.textContent = `/ ${total}`;
      this.prev.total = total;
    }
    if (Math.abs(time - this.prev.time) >= 1) {
      e.timeHud.textContent = fmtTime(time);
      this.prev.time = Math.floor(time);
    }
    const mult = jumpMult.toFixed(1);
    if (mult !== this.prev.mult) {
      e.jumpMult.textContent = `×${mult}`;
      this.prev.mult = mult;
    }
    e.jumpFill.style.width = `${Math.round(jumpPct * 100)}%`;
    e.jumpShell.classList.toggle('hot', hot === 'hot');
    e.jumpShell.classList.toggle('max', hot === 'max');
    if (world !== this.prev.world) {
      e.worldLabel.textContent = world;
      this.prev.world = world;
    }
    if (levelName !== this.prev.name) {
      e.levelName.textContent = levelName;
      this.prev.name = levelName;
    }
  }

  resetHUDCache() {
    this.prev = { coins: -1, total: -1, time: -1, mult: -1, world: '', name: '', hot: null };
  }

  banner(kicker, title, sub) {
    const e = this.el;
    e.bannerKicker.textContent = kicker;
    e.bannerTitle.textContent = title;
    e.bannerSub.textContent = sub;
    e.banner.classList.remove('show');
    void e.banner.offsetWidth;
    e.banner.classList.add('show');
    clearTimeout(this.bannerTimer);
    this.bannerTimer = setTimeout(() => e.banner.classList.remove('show'), 2600);
  }

  hideBanner() {
    clearTimeout(this.bannerTimer);
    this.el.banner.classList.remove('show');
  }

  toast(text, duration = 1600) {
    const e = this.el;
    e.toast.textContent = text;
    e.toast.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => e.toast.classList.remove('show'), duration);
  }

  hideToast() {
    clearTimeout(this.toastTimer);
    this.el.toast.classList.remove('show');
  }

  setSoundMuted(muted) {
    const b = this.el.soundBtn;
    b.classList.toggle('muted', muted);
    b.setAttribute('aria-pressed', String(muted));
    b.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound');
  }

  showPause({ coins, total, mult, hearts }) {
    this.el.pauseCoins.textContent = `${coins} / ${total}`;
    this.el.pauseJump.textContent = `×${mult.toFixed(1)}`;
    this.el.pauseHearts.textContent = '♥'.repeat(hearts) + '♡'.repeat(Math.max(0, 3 - hearts));
    this.showScreen('pauseScreen');
  }

  showClear({ title, coins, total, time, mult, flavor, button }) {
    this.el.clearTitle.textContent = title;
    this.el.clearCoins.textContent = `${coins} / ${total}`;
    this.el.clearTime.textContent = fmtTime(time);
    this.el.clearJump.textContent = `×${mult.toFixed(1)}`;
    this.el.clearFlavor.textContent = flavor;
    this.el.nextBtn.textContent = button;
    this.showScreen('clearScreen');
  }

  showGameOver({ coins, level, line }) {
    this.el.overCoins.textContent = coins;
    this.el.overLevel.textContent = level;
    this.el.gameoverLine.textContent = line;
    this.showScreen('gameoverScreen');
  }

  showWin({ coins, time, bestMult, flavor, bestLine }) {
    this.el.winCoins.textContent = coins;
    this.el.winTime.textContent = fmtTime(time);
    this.el.winBest.textContent = `×${bestMult.toFixed(1)}`;
    this.el.winFlavor.textContent = flavor;
    this.el.winBestLine.textContent = bestLine;
    this.showScreen('winScreen');
  }

  setBestLine(best) {
    const e = this.el.bestLine;
    if (!best) {
      e.textContent = 'No runs yet — be the first!';
      return;
    }
    e.textContent = `Best run: ${best.coins} coins · ${fmtTime(best.time)}`;
  }
}

content.text:
Now the big one: game.js. Let's plan the code structure in detail and write carefully.

Constants:
```js
import { makeLevel, TILE, WORLD_H, THEMES, ENEMY_DEFS } from './levels.js';
import { UI } from './ui.js'; // no, game receives ui
```
Game imports not UI.

```js
const W = 30, H = 42; // player
const BASE_JUMP = 730;
const JUMP_RANGE = 790;
const JUMP_CURVE = 32;
const GRAVITY = 2200;
const MAX_FALL = 1250;
const RUN_MAX = 300;
const ACCEL = 2500;
const AIR_ACCEL = 1750;
const FRICTION = 2900;
const COYOTE = 0.1;
const BUFFER = 0.13;
const MAX_HEARTS = 3;
```

Helper clamp, lerp, hash, roundRect, ease.

Class Game:

constructor(canvas, ui, sound):
- this.canvas, ctx
- dpr, cssW/H, viewW/H, scale
- camera {x,y}, camTarget...
- state 'title'
- input flags
- jumpBuffer, jumpHeld
- time global 0
- levelIndex, level, player, coins, particles, texts, popCoins
- shake, flash
- clearedT, deathT
- stats: levelResults, runTime, hearts, coinsThisLevel, stompsThisLevel, jumpsThisLevel, maxMult
- pendingAction
- titleLevel = makeLevel(0)
- resize listener, ResizeObserver
- bindInput
- loadLevel(0, true); position camera; this.state='title'; this.attract=0
- best = loadStorage
- ui.setBestLine
- ui.setSoundMuted(sound.muted)
- loop via requestAnimationFrame.

Sizing:
```js
resize(){
  const rect = canvas.getBoundingClientRect(); // CSS size
  this.cssW = Math.max(1, rect.width); this.cssH = ...;
  const dpr = Math.min(window.devicePixelRatio||1, 2);
  canvas.width = Math.round(cssW*dpr); ...
  const aspect = cssW/cssH;
  let viewH, viewW;
  if (aspect >= 1.08) { viewH = 560; viewW = viewH*aspect; if (viewW > 1060){ viewW=1060; viewH=viewW/aspect;} }
  else { viewW = 420; viewH = viewW/aspect; if (viewH > 900){ viewH=900; viewW=viewH*aspect; } }
  this.viewW=viewW; this.viewH=viewH; this.scale=cssW/viewW;
  this.camera bounds recompute maybe.
}
```
Wait for portrait aspect 0.75 tablet: viewW=420, viewH=560. Here viewH 560 < world 720; fine. Scale 768/420=1.83. Good.
For desktop 1280x800 aspect 1.6: viewW=896, viewH=560, scale=1.43.
For 390x844 aspect .462: viewW=420, viewH=909 → cap 900 → viewW=415.4, scale .939.
For ultrawide 1.777: viewW=995.
For 1280x720: viewW=995, scale 1.286.
Hmm desktop UI text world fonts scaled 1.28; fine.

Set canvas style? CSS handles.

Camera:
```js
camera = {x:0,y:0}
snapCamera() { compute desired and set }
desiredCamera(){
  const p = this.player;
  const targetX = p.x + p.w/2 + p.facing*this.viewW*0.06 - this.viewW*0.42;
  const targetY = p.y + p.h*0.6 - this.viewH*0.58 - Math.min(0,p.vy)*0.06;
  clamp...
  if (this.viewH >= this.level.worldH) { y = this.level.worldH - this.viewH; } else clamp 0..worldH-viewH
  x clamp 0..max(0,worldW-viewW)
}
updateCamera(dt){
  const tx,ty; smoothing 1-exp(-dt*(onGround?9:5)); 
}
```
For title: use attract camera independent.

Actually when player jumps high, camera y target clamped 0; fine.

Scale-aware: with viewH 900 > 720, y = 720-900=-180 (sky above). Good.

Camera x when viewW > worldW (impossible; world 6000+) fine.

Player creation:
```js
makePlayer() {
  const l=this.level;
  const spawn = this.respawnPoint();
  return {x:spawn.x, y:spawn.y-H, w:W,h:H,vx:0,vy:0,onGround:false, facing:1,
   coyote:0, jumpBuffer:0, invuln:1.2, anim:0, squash:0, carrier:null, prevY:..., dead:false, state:'idle', runDust:0, springT:0, powerGlow:0};
}
```
Initial invuln maybe 0.8 so no accidental. Spawn feet at level.spawn.y (576) - H.

Input methods:
```js
setMove(dir, on) // dir 'left'|'right'
pressJump(){ if(state==='playing'){ this.input.jump=true; this.player.jumpBuffer=BUFFER; } else { this.input.jump=true; } }
releaseJump(){ this.input.jump=false; if(state==='playing' && player.vy < -180) player.vy *= 0.48; }
```
Keyboard handled in main? Game.bindKeyboard. On keydown call pressJump only if not repeat; on keyup release. For menu screens, keyboard Enter/Space handled by main UI? Let main handle Play via Enter. Game key handler should ignore keys in overlays except pause. Pressing space in pause shouldn't jump. So `pressJump` checks state==='playing' for buffer but still sets input.jump. On resume, holding jump could auto-jump? buffer only set on press; fine.

Also touch release calls releaseJump.

