Player update details:

```js
updatePlayer(dt){
  const p=this.player;
  p.prevY = p.y;
  // move with carrier from previous frame (handled in movers update)
  const dir = (this.input.right?1:0) - (this.input.left?1:0);
  if (dir!==0) p.facing = dir;
  const accel = p.onGround?ACCEL:AIR_ACCEL;
  if (dir!==0) {
    p.vx += dir*accel*dt;
    // extra control if opposite direction
    p.vx = clamp(p.vx, -RUN_MAX*1.05, RUN_MAX*1.05);
  } else {
    const fr = (p.onGround?FRICTION:FRICTION*0.35)*dt;
    if (p.vx > 0) p.vx = Math.max(0,p.vx-fr); else p.vx = Math.min(0,p.vx+fr);
  }
  // clamp to max run
  if (Math.abs(p.vx)>RUN_MAX) p.vx = Math.sign(p.vx)*Math.max(RUN_MAX, Math.abs(p.vx)-1200*dt);

  // jump buffer/coyote
  p.jumpBuffer = Math.max(0,p.jumpBuffer-dt);
  if (p.jumpBuffer>0 && (p.onGround || p.coyote>0)) this.doJump();
  p.coyote = p.onGround ? COYOTE : Math.max(0,p.coyote-dt);

  // gravity
  p.vy += GRAVITY*dt;
  if (p.vy>MAX_FALL) p.vy=MAX_FALL;
  p.onGround=false;
  // X collision
  p.x += p.vx*dt;
  this.collideX(p);
  // Y collision
  p.y += p.vy*dt;
  const wasFalling = p.vy>0;
  this.collideY(p, wasFalling);
  // world bounds
  if (p.x<0){p.x=0;p.vx=0}
  if (p.x+p.w>level.worldW){...}
  if (p.y<0){p.y=0; if(p.vy<0)p.vy=0}
  // coyote if landed
  if (p.onGround) p.coyote=COYOTE;
  // anim
  p.anim += dt*(p.onGround ? Math.min(1.6, 0.6+Math.abs(p.vx)/420) : 0.7);
  p.squash = Math.max(0,p.squash-dt*4.5);
  p.invuln = Math.max(0,p.invuln-dt);
  p.springT = Math.max(0,p.springT-dt*3);
  // fall
  if (p.y > worldH+160) this.pitFall();
  // coins
  for coin...
  // enemies handled separate
  // checkpoint
  // goal
  // dust
}
```
