Camera update:
```js
computeCameraTarget(){
  const p=this.player, l=this.level;
  let tx = p.x + p.w/2 - this.viewW*0.44 + p.facing*this.viewW*0.05 + p.vx*0.06;
  let ty = p.y + p.h*0.55 - this.viewH*0.56 + Math.min(0,p.vy)*0.05;
  if (this.viewW >= l.worldW) tx = (l.worldW-this.viewW)/2;
  else tx = clamp(tx, 0, l.worldW-this.viewW);
  if (this.viewH >= l.worldH) ty = l.worldH - this.viewH;
  else ty = clamp(ty, 0, l.worldH-this.viewH);
  return {tx,ty};
}
updateCamera(dt){
  const {tx,ty}=...
  const k = 1 - Math.exp(-dt*(this.player.onGround? 9 : 5.5));
  this.camera.x += (tx-this.camera.x)*k;
  this.camera.y += (ty-this.camera.y)*k;
}
```
