Enemy update:
```js
updateEnemies(dt){
 const solids=this.level.solids;
 for(const e of this.level.enemies){
  if(e.dead){ e.deadT+=dt; continue; }
  e.t+=dt;
  if(e.type==='flyer'){
    e.x += e.vx*dt;
    const range=e.range||150;
    if(e.x < e.spawnX-range){ e.x=e.spawnX-range; e.vx=Math.abs(e.vx); }
    if(e.x > e.spawnX+range){ e.x=e.spawnX+range; e.vx=-Math.abs(e.vx); }
    e.y = e.baseY + Math.sin(e.t*2.2)*16;
  } else {
    e.vy += GRAVITY*dt;
    e.x += e.vx*dt;
    for(const s of solids){
      if(this.overlaps(e,s)){
        if(e.vx>0) e.x=s.x-e.w-0.01; else if(e.vx<0) e.x=s.x+s.w+0.01;
        e.vx*=-1; break;
      }
    }
    e.y += e.vy*dt;
    e.grounded=false;
    for(const s of solids){
      if(this.overlaps(e,s)){
        if(e.vy>0){ e.y=s.y-e.h; e.vy=0; e.grounded=true; }
        else if(e.vy<0){ e.y=s.y+s.h; e.vy=0; }
      }
    }
    if(e.grounded){
      const aheadX = e.vx>0 ? e.x+e.w+3 : e.x-3;
      const probeY = e.y+e.h+8;
      if(!this.solidAt(aheadX,probeY,solids)) { e.vx*=-1; }
    }
    if(e.y > this.level.worldH+120){ e.alive=false; }
  }
  // player collision
  if(!e.dead && this.state==='playing' && this.overlaps(this.player,e)){
    const p=this.player;
    const feet=p.y+p.h;
    const cameFromAbove = p.prevY + p.h <= e.y + 16;
    const stomping = p.vy > 20 && cameFromAbove && feet < e.y + e.h*0.8;
    if(stomping && e.type!=='spiky'){
      e.dead=true; e.deadT=0; e.squash=1;
      p.vy = -560; p.onGround=false; p.coyote=0; p.y = e.y - p.h - 1;
      this.stompsThisLevel++;
      this.sound.stomp();
      this.spawnBurst(e.x+e.w/2,e.y+e.h/2,10,['#fff1d0','#e8a87c','#c97a52'],170,false);
      this.addText(e.x+e.w/2,e.y-10,'BONK!','#ffe89a',16);
      this.shake=Math.max(this.shake,3);
      if(this.input.jump) p.jumpBuffer=JUMP_BUFFER;
    } else {
      this.damage(e);
    }
  }
 }
 this.level.enemies = this.level.enemies.filter(e => !e.dead ? e.alive : e.deadT < 0.8);
}
```
