  ctx.lineWidth = 8.5;
  ctx.beginPath();
  ctx.moveTo(sx, sy);
  ctx.quadraticCurveTo((sx + hx) / 2 + 2, (sy + hy) / 2, hx, hy);
  ctx.stroke();
  ctx.strokeStyle = color;
  ctx.lineWidth = 5.5;
  ctx.stroke();
  ctx.fillStyle = skin;
  ctx.strokeStyle = outline;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(hx, hy, 3.2, 0, TAU);
  ctx.fill();
  ctx.stroke();
}

function drawLeg(ctx, hx, hy, ax, ay, color, skin, outline) {
  ctx.lineCap = 'round';
  ctx.strokeStyle = outline;
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.moveTo(hx, hy);
  ctx.lineTo(ax, ay);
  ctx.stroke();
  ctx.strokeStyle = color;
  ctx.lineWidth = 7;
  ctx.stroke();
}

function drawShoe(ctx, x, y, rot, color) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.fillStyle = color;
  ctx.strokeStyle = '#2a140c';
  ctx.lineWidth = 1.6;
  roundRect(ctx, -2, -5, 14, 7, 3);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = 'rgba(0,0,0,.32)';
  roundRect(ctx, -2, 0, 14, 2.5, 1);
  ctx.fill();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/*  Particles + text                                                   */
/* ------------------------------------------------------------------ */

function drawParticleField(g, ctx) {
  for (const p of g.particles) {
    const a = clamp(p.life / p.maxLife, 0, 1);
    ctx.globalAlpha = a;
    if (p.kind === 'confetti') {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      ctx.fillStyle = p.color;
      ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
      ctx.restore();
    } else if (p.kind === 'dust') {
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.5 + (1 - a) * 0.7), 0, TAU);
      ctx.fill();
    } else {
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.6 + a * 0.5), 0, TAU);
      ctx.fill();
      if (p.size > 3.5) {
        ctx.globalAlpha = a * 0.65;
        ctx.fillStyle = '#fffbe0';
        ctx.beginPath();
        ctx.arc(p.x - p.size * 0.2, p.y - p.size * 0.2, p.size * 0.3, 0, TAU);
        ctx.fill();
      }
    }
  }
  ctx.globalAlpha = 1;
}

function drawFloatingTexts(g, ctx) {
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const t of g.texts) {
    const a = clamp(t.life / t.maxLife, 0, 1);
    const pop = 1 + (1 - a) * 0.15;
    ctx.save();
    ctx.translate(t.x, t.y);
    ctx.scale(pop, pop);
    ctx.globalAlpha = Math.min(1, a * 2.2);
    ctx.font = `900 ${t.size}px "Trebuchet MS", sans-serif`;
    ctx.lineWidth = Math.max(3, t.size * 0.22);
    ctx.strokeStyle = 'rgba(12, 14, 32, .8)';
    ctx.strokeText(t.text, 0, 0);
    ctx.fillStyle = t.color;
    ctx.fillText(t.text, 0, 0);
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
}
