102:       const raw = localStorage.getItem(BEST_KEY);
103:       if (!raw) return null;
104:       const v = JSON.parse(raw);
105:       if (typeof v.coins === 'number' && typeof v.time === 'number') return v;
106:     } catch {}
107:     return null;
108:   }
109: 
110:   saveBest(coins, time) {
111:     const prev = this.best;
112:     const better = !prev || coins > prev.coins || (coins === prev.coins && time < prev.time);
113:     if (better) {
114:       this.best = { coins, time };
115:       try { localStorage.setItem(BEST_KEY, JSON.stringify(this.best)); } catch {}
116:     }
117:     return better;
118:   }
