140:       x: sp.x - PLAYER_W / 2,
141:       y: sp.y - PLAYER_H,
142:       w: PLAYER_W,
143:       h: PLAYER_H,
144:       vx: 0,
145:       vy: 0,
146:       facing: 1,
147:       onGround: false,
148:       coyote: 0,
149:       jumpBuffer: 0,
150:       invuln: 0,
