162:   resize() {
163:     const rect = this.canvas.getBoundingClientRect();
164:     const cssW = Math.max(1, rect.width || window.innerWidth);
165:     const cssH = Math.max(1, rect.height || window.innerHeight);
166:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
167: 
168:     this.cssW = cssW;
169:     this.cssH = cssH;
170:     this.dpr = dpr;
171:     this.canvas.width = Math.round(cssW * dpr);
172:     this.canvas.height = Math.round(cssH * dpr);
173: 
174:     const aspect = cssW / cssH;
175:     let viewW;
176:     let viewH;
177:     if (aspect >= 1.08) {
178:       viewH = 560;
179:       viewW = viewH * aspect;
180:       if (viewW > 1060) {
181:         viewW = 1060;
182:         viewH = viewW / aspect;
183:       }
184:     } else {
185:       viewW = 420;
186:       viewH = viewW / aspect;
187:       if (viewH > 900) {
188:         viewH = 900;
189:         viewW = viewH * aspect;
190:       }
191:     }
192:     this.viewW = viewW;
193:     this.viewH = viewH;
194:     this.scale = cssW / viewW;
195: 
196:     const ctx = this.ctx;
197:     const v = ctx.createRadialGradient(
198:       cssW / 2, cssH * 0.46, Math.min(cssW, cssH) * 0.22,
199:       cssW / 2, cssH * 0.52, Math.max(cssW, cssH) * 0.74,
200:     );
201:     v.addColorStop(0, 'rgba(0,0,0,0)');
202:     v.addColorStop(0.72, 'rgba(3,6,18,.08)');
203:     v.addColorStop(1, 'rgba(3,5,15,.46)');
