207:   cameraTarget() {
208:     const l = this.level;
209:     const p = this.player;
210:     let tx = p ? p.x + p.w / 2 - this.viewW * 0.44 + p.facing * this.viewW * 0.045 : 0;
211:     let ty = p ? p.y + p.h * 0.55 - this.viewH * 0.56 - Math.min(0, p.vy) * 0.045 : 0;
212:     if (this.viewW >= l.worldW) tx = (l.worldW - this.viewW) / 2;
213:     else tx = clamp(tx, 0, l.worldW - this.viewW);
214:     if (this.viewH >= l.worldH) ty = l.worldH - this.viewH;
215:     else ty = clamp(ty, 0, l.worldH - this.viewH);
216:     return { tx, ty };
