225:   updateCamera(dt) {
226:     const { tx, ty } = this.cameraTarget();
227:     const k = 1 - Math.exp(-dt * (this.player && this.player.onGround ? 9 : 5.5));
228:     this.camera.x += (tx - this.camera.x) * k;
229:     this.camera.y += (ty - this.camera.y) * k;
230:   }
