232:   snapTitleCamera() {
233:     if (!this.level) return;
234:     this.camera.y = this.viewH >= this.level.worldH
235:       ? this.level.worldH - this.viewH
236:       : clamp(12 * TILE - this.viewH * 0.78, 0, this.level.worldH - this.viewH);
237:     this.camera.x = 200;
238:     this.attract = 0;
