241:   updateTitle(dt) {
242:     this.attract += dt;
243:     const maxX = Math.max(0, this.level.worldW - this.viewW - 240);
244:     const span = Math.min(maxX, 1700);
245:     const t = (Math.sin(this.attract * 0.13 - Math.PI / 2) + 1) / 2;
246:     this.camera.x = 200 + t * span;
247:     if (this.player) this.player.anim += dt * 0.5;
