316:     const totalTime = this.results.reduce((a, r) => a + (r ? r.time : 0), 0);
317:     const possible = this.results.reduce((a, r) => a + (r ? r.total : 0), 0);
318:     const ratio = possible > 0 ? totalCoins / possible : 0;
319:     let flavor = 'You made it. The castle salutes you.';
320:     if (ratio >= 0.96) flavor = 'COIN MASTER — not a single coin left behind.';
321:     else if (ratio >= 0.78) flavor = 'Sky legend. The clouds know your name.';
322:     else if (ratio >= 0.5) flavor = 'A fine run. Every coin made you fly.';
323:     const isBest = this.saveBest(totalCoins, totalTime);
