418:   bindEvents() {
419:     window.addEventListener('keydown', (e) => {
420:       const k = e.key.toLowerCase();
421:       if (k === 'arrowleft' || k === 'arrowright' || k === 'arrowup' || k === 'arrowdown' || k === ' ') {
422:         e.preventDefault();
423:       }
424:       if (k === 'arrowleft' || k === 'a') this.setMove('left', true);
425:       if (k === 'arrowright' || k === 'd') this.setMove('right', true);
426:       if (k === ' ' || k === 'arrowup' || k === 'w') {
427:         if (!e.repeat) this.pressJump();
428:       }
429:       if (k === 'escape' || k === 'p') {
430:         if (this.state === 'playing' || this.state === 'paused') this.togglePause();
431:       }
432:       if (e.key === 'Enter') {
433:         if (this.state === 'title') this.startRun();
434:         else if (this.state === 'paused') this.togglePause();
435:         else if (this.state === 'gameover') this.retry();
436:         else if (this.state === 'clear') this.advance();
437:         else if (this.state === 'win') this.startRun();
438:       }
439:     });
