441:     window.addEventListener('keyup', (e) => {
442:       const k = e.key.toLowerCase();
443:       if (k === 'arrowleft' || k === 'a') this.setMove('left', false);
444:       if (k === 'arrowright' || k === 'd') this.setMove('right', false);
445:       if (k === ' ' || k === 'arrowup' || k === 'w') this.releaseJump();
