460:   loop(ts) {
461:     if (!this.lastTs) this.lastTs = ts;
462:     let dt = (ts - this.lastTs) / 1000;
463:     this.lastTs = ts;
464:     if (dt > 0.1) dt = 0.1;
465:     if (dt < 0) dt = 0;
466:     this.animClock += dt;
467: 
468:     this.accumulator = Math.min(this.accumulator + dt, 0.2);
469:     let steps = 0;
470:     while (this.accumulator >= 1 / 60 && steps < 8) {
471:       this.update(1 / 60);
472:       this.accumulator -= 1 / 60;
473:       steps++;
474:     }
475:     this.render();
476:     this.raf = requestAnimationFrame((t) => this.loop(t));
477:   }
