479:   update(dt) {
480:     this.shake = Math.max(0, this.shake - dt * 26);
481:     if (this.flash > 0) this.flash = Math.max(0, this.flash - dt * 2.1);
482: 
483:     switch (this.state) {
484:       case 'title':
485:         this.updateTitle(dt);
486:         break;
487:       case 'playing':
488:         this.levelTime += dt;
489:         this.updateMovers(dt);
490:         this.updatePlayer(dt);
491:         if (this.state === 'playing') this.updateEnemies(dt);
492:         if (this.state === 'playing') this.updateBlocks(dt);
493:         this.updateParticles(dt);
494:         this.updateTexts(dt);
495:         this.syncHUD();
496:         if (this.state === 'playing') this.updateCamera(dt);
497:         break;
498:       case 'clearing':
499:         this.clearT += dt;
500:         this.updateParticles(dt);
501:         this.updateTexts(dt);
502:         this.updateCamera(dt);
503:         if (this.clearT > 1.4) this.finishClear();
504:         break;
505:       case 'clear':
506:       case 'gameover':
507:       case 'win':
508:         this.updateParticles(dt);
509:         this.updateTexts(dt);
510:         break;
511:       default:
512:         break;
513:     }
514:   }
515: 
516:   syncHUD() {
517:     const mult = this.jumpMult();
518:     if (mult > this.maxRunMult) this.maxRunMult = mult;
519:     const pct = Math.min(1, this.coinsThisLevel / 55);
520:     const hot = pct >= 1 ? 'max' : pct >= 0.55 ? 'hot' : null;
521:     this.ui.updateHUD({
522:       coins: this.coinsThisLevel,
523:       total: this.level.totalCoins,
524:       jumpMult: mult,
525:       jumpPct: pct,
526:       time: this.levelTime,
527:       world: `WORLD ${this.level.id}`,
528:       levelName: this.level.name,
529:       hot,
530:     });
531:   }
532: 
533:   jumpSpeed() {
534:     return BASE_JUMP + JUMP_RANGE * (1 - Math.exp(-this.coinsThisLevel / JUMP_CURVE));
535:   }
536: 
537:   jumpMult() {
538:     return this.jumpSpeed() / BASE_JUMP;
539:   }
540: 
541:   overlaps(a, b) {
542:     return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
543:   }
544: 
545:   solidAt(x, y, solids) {
546:     for (const s of solids) {
547:       if (x >= s.x && x <= s.x + s.w && y >= s.y && y <= s.y + s.h) return true;
548:     }
549:     return false;
550:   }
551: 
552:   updateMovers(dt) {
553:     for (const m of this.level.movers) {
554:       m.prevX = m.x;
555:       m.prevY = m.y;
556:       const off = Math.sin(this.levelTime * m.speed + m.phase) * m.range;
557:       if (m.axis === 'x') {
558:         m.x = m.ox + off;
559:         m.y = m.oy;
560:       } else {
561:         m.x = m.ox;
562:         m.y = m.oy + off;
563:       }
564:       if (this.player && this.player.carrier === m) {
565:         this.player.x += m.x - m.prevX;
566:         this.player.y += m.y - m.prevY;
567:       }
568:     }
569:     if (this.player) this.player.carrier = null;
570:   }
571: 
572:   updatePlayer(dt) {
573:     const p = this.player;
574:     const l = this.level;
575:     p.prevY = p.y;
576: 
577:     const dir = (this.input.right ? 1 : 0) - (this.input.left ? 1 : 0);
578:     if (dir !== 0) p.facing = dir;
579: 
580:     const accel = p.onGround ? ACCEL : AIR_ACCEL;
581:     if (dir !== 0) {
582:       const turning = p.vx !== 0 && Math.sign(dir) !== Math.sign(p.vx);
583:       p.vx += dir * accel * (turning ? 1.7 : 1) * dt;
584:       p.vx = clamp(p.vx, -RUN_MAX * 1.06, RUN_MAX * 1.06);
585:     } else {
586:       const fr = (p.onGround ? FRICTION : FRICTION * 0.3) * dt;
587:       p.vx = approach(p.vx, 0, fr);
588:     }
589:     if (Math.abs(p.vx) > RUN_MAX) {
590:       p.vx = approach(p.vx, Math.sign(p.vx) * RUN_MAX, 2000 * dt);
591:     }
592: 
593:     p.jumpBuffer = Math.max(0, p.jumpBuffer - dt);
594:     const canJump = p.onGround || p.coyote > 0;
595:     if (p.jumpBuffer > 0 && canJump) this.doJump();
596:     p.coyote = p.onGround ? COYOTE : Math.max(0, p.coyote - dt);
597: 
598:     p.vy = Math.min(p.vy + GRAVITY * dt, MAX_FALL);
599: 
600:     const wasGrounded = p.onGround;
601:     p.onGround = false;
602: 
603:     p.x += p.vx * dt;
604:     this.collideX(p);
605: 
606:     const fallSpeed = p.vy;
607:     p.y += p.vy * dt;
608:     this.collideY(p);
609: 
610:     if (p.x < 0) {
611:       p.x = 0;
612:       p.vx = Math.max(0, p.vx);
613:     }
614:     if (p.x + p.w > l.worldW) {
615:       p.x = l.worldW - p.w;
616:       p.vx = Math.min(0, p.vx);
617:     }
618:     if (p.y < 0) {
619:       p.y = 0;
620:       if (p.vy < 0) p.vy = 0;
621:     }
